using System;

namespace BikeShop
{
    // The one mistake a report can be asked to make: a From date after the
    // To date. It is a class of its own so the report form can catch this
    // mistake by name and nothing else.
    public class InvalidDateRangeException : Exception
    {
        public DateTime FromDate { get; set; }
        public DateTime ToDate { get; set; }

        public InvalidDateRangeException(DateTime fromDate, DateTime toDate)
            : base("The From date (" + fromDate.ToString("d MMM yyyy")
                  + ") is after the To date (" + toDate.ToString("d MMM yyyy")
                  + "). Choose a From date on or before the To date.")
        {
            FromDate = fromDate;
            ToDate = toDate;
        }
    }
}

using System;
using System.Data;

namespace BikeShop.Data
{
    public static class ReportData
    {
        // Every report starts with the same check. A From date after the To
        // date is refused before SQL Server is asked anything.
        private static void CheckRange(DateTime fromDate, DateTime toDate)
        {
            if (fromDate.Date > toDate.Date)
            {
                throw new InvalidDateRangeException(fromDate.Date, toDate.Date);
            }
        }

        public static DataTable MechanicWorkload(DateTime fromDate,
            DateTime toDate)
        {
            CheckRange(fromDate, toDate);
            return Db.GetTable("usp_Report_MechanicWorkload",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }

        public static DataTable Income(DateTime fromDate, DateTime toDate)
        {
            CheckRange(fromDate, toDate);
            return Db.GetTable("usp_Report_Income",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }

        public static DataTable Activity(DateTime fromDate, DateTime toDate)
        {
            CheckRange(fromDate, toDate);
            return Db.GetTable("usp_Report_Activity",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }

        public static DataTable PopularServices(DateTime fromDate,
            DateTime toDate)
        {
            CheckRange(fromDate, toDate);
            return Db.GetTable("usp_Report_PopularServices",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }

        public static DataTable PopularParts(DateTime fromDate,
            DateTime toDate)
        {
            CheckRange(fromDate, toDate);
            return Db.GetTable("usp_Report_PopularParts",
                Db.P("@FromDate", fromDate.Date), Db.P("@ToDate", toDate.Date));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Windows.Forms;
using BikeShop.Data;
using BikeShop.Models;

namespace BikeShop.Forms
{
    public partial class frmReports : Form
    {
        public frmReports()
        {
            InitializeComponent();
        }

        private void frmReports_Load(object sender, EventArgs e)
        {
            cboReport.SelectedIndex = 0;
            dtpFrom.Value = DateTime.Today.AddDays(-30);
            dtpTo.Value = DateTime.Today;
            lblTotal.Text = "";
        }

        #region Run
        private void btnRun_Click(object sender, EventArgs e)
        {
            DataTable table;
            try
            {
                if (cboReport.SelectedIndex == 0)
                {
                    table = ReportData.MechanicWorkload(dtpFrom.Value,
                        dtpTo.Value);
                }
                else if (cboReport.SelectedIndex == 1)
                {
                    table = ReportData.Income(dtpFrom.Value, dtpTo.Value);
                }
                else if (cboReport.SelectedIndex == 2)
                {
                    table = ReportData.Activity(dtpFrom.Value, dtpTo.Value);
                }
                else if (cboReport.SelectedIndex == 3)
                {
                    table = ReportData.PopularServices(dtpFrom.Value,
                        dtpTo.Value);
                }
                else
                {
                    table = ReportData.PopularParts(dtpFrom.Value,
                        dtpTo.Value);
                }
            }
            catch (InvalidDateRangeException ex)
            {
                // The From date is after the To date: say so, leave the grid
                // as it was, and put the cursor back in From.
                Msg.Problem(ex.Message);
                dtpFrom.Focus();
                return;
            }

            dgvReport.DataSource = table;
            Grid.Tidy(dgvReport);
            ShowTotal();
            btnCopy.Enabled = dgvReport.Rows.Count > 0;
        }

        // One plain sentence under the grid, so the answer to the report's
        // question is on screen, not left to a calculator.
        private void ShowTotal()
        {
            int n = dgvReport.Rows.Count;
            if (n == 0)
            {
                lblTotal.Text = "Nothing in those dates.";
            }
            else if (cboReport.SelectedIndex == 0)
            {
                lblTotal.Text = "Mechanics listed: " + n
                    + ". Workshop income in these dates: £"
                    + SumColumn("Income").ToString("#,##0.00") + ".";
            }
            else if (cboReport.SelectedIndex == 1)
            {
                lblTotal.Text = "Lines listed: " + n
                    + ". Total income in these dates: £"
                    + SumColumn("Income").ToString("#,##0.00") + ".";
            }
            else if (cboReport.SelectedIndex == 2)
            {
                lblTotal.Text =
                    "Each line counts one kind of thing in these dates.";
            }
            else if (cboReport.SelectedIndex == 3)
            {
                DataGridViewRow top = dgvReport.Rows[0];
                int booked = Convert.ToInt32(top.Cells["Bookings"].Value);
                if (booked == 0)
                {
                    lblTotal.Text = "Services listed: " + n
                        + ". None were booked in these dates.";
                }
                else
                {
                    lblTotal.Text = "Services listed: " + n
                        + ". Most popular: " + top.Cells["Service"].Value
                        + ", booked " + Times(booked) + ".";
                }
            }
            else
            {
                DataGridViewRow top = dgvReport.Rows[0];
                int sold = Convert.ToInt32(top.Cells["Sold"].Value);
                if (sold == 0)
                {
                    lblTotal.Text = "Parts listed: " + n
                        + ". None were sold in these dates.";
                }
                else
                {
                    lblTotal.Text = "Parts listed: " + n
                        + ". Best seller: " + top.Cells["Part"].Value
                        + ", " + sold + " sold.";
                }
            }
        }

        // Adds up one column of the grid.
        private decimal SumColumn(string column)
        {
            decimal total = 0;
            foreach (DataGridViewRow row in dgvReport.Rows)
            {
                total = total + Convert.ToDecimal(row.Cells[column].Value);
            }
            return total;
        }

        // 1 becomes "once", 2 becomes "twice", anything else "5 times".
        private string Times(int n)
        {
            if (n == 1)
            {
                return "once";
            }
            else if (n == 2)
            {
                return "twice";
            }
            else
            {
                return n + " times";
            }
        }
        #endregion

        #region Copy
        // Copies the grid with its headers, ready to paste into Word or Excel
        // for the user guide or the test evidence.
        private void btnCopy_Click(object sender, EventArgs e)
        {
            dgvReport.ClipboardCopyMode =
                DataGridViewClipboardCopyMode.EnableAlwaysIncludeHeaderText;
            dgvReport.SelectAll();
            DataObject content = dgvReport.GetClipboardContent();
            if (content != null)
            {
                Clipboard.SetDataObject(content);
            }
            dgvReport.ClearSelection();
            Msg.Info("Copied. Paste it into Word or Excel.");
        }
        #endregion

        private void btnClose_Click(object sender, EventArgs e)
        {
            Close();
        }
    }
}
